<section class="grid gap-5 lg:grid-cols-[380px_1fr]"><article class="rounded-2xl border border-violet-200 bg-white p-5 shadow-sm"><h2 class="font-semibold">Nuevo vínculo o transición</h2><form method="post" action="index.php?url=vinculo_laboral_guardar" data-confirmar-accion="transicion-laboral" class="mt-4 grid gap-3"><?= campoCsrf() ?><label class="form-label">Persona<select required name="id_persona" class="form-input"><option value="">Seleccione</option><?php foreach($personas as $p): ?><option value="<?= $p['id_persona'] ?>"><?= htmlspecialchars($p['apellidos'].', '.$p['nombres'].' · '.($p['codigo_trabajador']?:'Sin código')) ?></option><?php endforeach; ?></select></label><label class="form-label">Nuevo tipo<select required name="tipo" class="form-input"><option value="DOCENTE">Docente</option><option value="ADMINISTRATIVO">Administrativo</option></select></label><label class="form-label">Cargo<input required name="cargo" placeholder="Ej. Director, Secretaria, Docente" class="form-input"></label><label class="form-label">Modalidad de pago<select name="modalidad_pago" class="form-input"><option value="MENSUAL">Mensual</option><option value="HORA">Por hora</option><option value="SESION">Por sesión</option></select></label><label class="form-label">Monto base<input required min="0" step=".01" type="number" name="monto_base" class="form-input"></label><div class="grid grid-cols-2 gap-3"><label class="form-label">Inicio<input required type="date" name="fecha_inicio" value="<?= date('Y-m-d') ?>" class="form-input"></label><label class="form-label">Fin <span class="font-normal text-slate-400">(opcional)</span><input type="date" name="fecha_fin" class="form-input"></label></div><button class="rounded-xl bg-violet-600 px-4 py-2.5 text-sm font-semibold text-white">Guardar vínculo</button></form></article><article class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div class="border-b border-slate-100 px-5 py-4"><h2 class="font-semibold">Historial laboral</h2></div><div class="overflow-x-auto"><table data-datatable data-page-options="5,10,25,50" class="min-w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500"><tr><th class="px-4 py-3">Persona</th><th class="px-4 py-3">Tipo</th><th class="px-4 py-3">Inicio</th><th class="px-4 py-3">Fin</th><th class="px-4 py-3">Estado</th></tr></thead><tbody class="divide-y divide-slate-100"><?php foreach($vinculos as $v): ?><tr><td class="px-4 py-3 font-medium"><?= htmlspecialchars($v['persona']) ?></td><td class="px-4 py-3"><?= htmlspecialchars($v['tipo']) ?></td><td class="px-4 py-3"><?= htmlspecialchars($v['fecha_inicio']) ?></td><td class="px-4 py-3"><?= htmlspecialchars($v['fecha_fin']?:'—') ?></td><td class="px-4 py-3"><span class="inline-flex rounded-full px-2.5 py-1 text-xs font-semibold <?= $v['estado']==='ACTIVO'?'bg-emerald-100 text-emerald-700':'bg-slate-200 text-slate-700' ?>"><?= htmlspecialchars($v['estado']) ?></span></td></tr><?php endforeach; ?></tbody></table></div></article></section>
